import{_ as e,o,c as d,a3 as a}from"./chunks/framework.jVlskimI.js";const b=JSON.parse('{"title":"📌 如何进服？","description":"","frontmatter":{},"headers":[],"relativePath":"Join-guide.md","filePath":"Join-guide.md"}'),r={name:"Join-guide.md"};function n(c,t,i,s,p,l){return o(),d("div",{"data-pagefind-body":!0},t[0]||(t[0]=[a('<h1 id="📌-如何进服" tabindex="-1">📌 如何进服？ <a class="header-anchor" href="#📌-如何进服" aria-label="Permalink to &quot;📌 如何进服？&quot;">​</a></h1><p><strong>🔹 第一步：📱 加入 QQ 群</strong></p><div align="center" style="margin:20px 0;"><a href="https://qm.qq.com/q/yourgroupurl" style="display:inline-block;background:#5572f3;color:white;font-weight:bold;font-size:1.1em;padding:12px 28px;border-radius:50px;text-decoration:none;box-shadow:0 4px 8px rgba(0,0,0,0.2);transition:all 0.2s ease;"> 点击加入 Inspurs 官方交流群 </a></div><hr><p><strong>🔹 第二步：🆔 获取你的游戏 ID</strong><br> 进入游戏主界面，即可看到你的游戏 ID，如下图所示：</p><img src="https://s41.ax1x.com/2026/04/13/peD34bV.png" alt="游戏ID位置示意" width="50%"><hr><p><strong>🔹 第三步：🤖 自助绑定白名单</strong></p><p><strong>在QQ群中发送以下图片内容<br>即可完成自助绑定白名单 <br>如下图所示：</strong></p><p><img src="https://s41.ax1x.com/2026/04/13/peD3T5F.png" alt="ID2"></p><p>示例：<code>绑定白名单 Steve</code></p><h3 id="绑定成功后-你就能加入服务器啦" tabindex="-1">绑定成功后，你就能加入服务器啦！ <a class="header-anchor" href="#绑定成功后-你就能加入服务器啦" aria-label="Permalink to &quot;绑定成功后，你就能加入服务器啦！&quot;">​</a></h3><blockquote><p>💡 如需解除绑定，可使用指令： 解绑白名单</p></blockquote><blockquote><p>推荐使用 Minecraft 基岩版 <code>1.21.132</code> 以获得最佳兼容性。</p></blockquote><hr><h2 id="🤖-qq-群机器人指令一览" tabindex="-1">🤖 QQ 群机器人指令一览 <a class="header-anchor" href="#🤖-qq-群机器人指令一览" aria-label="Permalink to &quot;🤖 QQ 群机器人指令一览&quot;">​</a></h2><p>Inspurs 服务器在 QQ 群内提供了便捷的机器人指令，让你在游戏外也能随时掌握服务器动态。</p><table tabindex="0"><thead><tr><th>指令格式</th><th>功能说明</th><th>示例</th></tr></thead><tbody><tr><td><code>绑定白名单 &lt;游戏ID&gt;</code></td><td>将你的 QQ 与游戏账号绑定，获得进服资格</td><td><code>绑定白名单 Steve</code></td></tr><tr><td><code>解绑白名单 </code></td><td>解除 QQ 与游戏账号的绑定</td><td><code>解绑白名单</code></td></tr><tr><td><code>查服</code></td><td>查询当前服务器在线人数及状态</td><td><code>查服</code></td></tr><tr><td><code>余额</code></td><td>查询自己游戏内的金币数量</td><td><code>余额</code></td></tr></tbody></table><blockquote><p>📌 所有指令直接发送到群内即可，机器人会自动响应。</p></blockquote>',19)]))}const u=e(r,[["render",n]]);export{b as __pageData,u as default};
